{
  "decision-route-a-balancing-rig-between-press-bays": "SELECT a.ticket_id AS first_ticket, b.ticket_id AS second_ticket, a.gain_hours + b.gain_hours AS recovered_hours FROM press_ticket AS a CROSS JOIN press_ticket AS b LEFT JOIN rig_transfer AS t ON t.from_bay = a.bay_code AND t.to_bay = b.bay_code WHERE a.ticket_id <> b.ticket_id AND b.begin_hour - a.end_hour >= CASE WHEN a.bay_code = b.bay_code THEN 0 ELSE t.travel_hours END ORDER BY recovered_hours DESC, b.end_hour ASC, a.ticket_id COLLATE BINARY ASC, b.ticket_id COLLATE BINARY ASC LIMIT 1",
  "decision-schedule-a-two-slot-patch-panel-move": "SELECT a.slot_no AS start_slot, b.slot_no AS end_slot, (SELECT COUNT(DISTINCT k.booth_code) FROM booth_booking AS k WHERE k.slot_no IN (a.slot_no, b.slot_no)) AS affected_booths, a.notice_id AS start_notice, b.notice_id AS end_notice FROM slot_notice AS a JOIN slot_notice AS b ON b.slot_no = a.slot_no + 1 WHERE a.work_ok = 1 AND b.work_ok = 1 ORDER BY affected_booths ASC, start_slot ASC LIMIT 1",
  "decision-schedule-after-business-day-lag": "WITH eligible_days AS (SELECT j.job, j.lag_business_days, p.day AS scheduled_date, ROW_NUMBER() OVER (PARTITION BY j.job ORDER BY p.day) AS business_day_no FROM jobs AS j JOIN planning_dates AS p ON p.day > j.release_date WHERE strftime('%w', p.day) BETWEEN '1' AND '5' AND NOT EXISTS (SELECT 1 FROM closures AS c WHERE c.closed_date = p.day)) SELECT job, scheduled_date FROM eligible_days WHERE business_day_no = lag_business_days ORDER BY scheduled_date ASC, job ASC",
  "decision-schedule-fixed-volume-pump-runs": "WITH flags(run) AS (VALUES (0), (1)), first_hour AS (SELECT f.run AS run_one, 2 + 4 * f.run - h.draw_kl AS level_one, f.run * h.run_cents AS cost_one FROM flags AS f CROSS JOIN pump_hour AS h WHERE h.hour_no = 1), second_hour AS (SELECT a.run_one, f.run AS run_two, a.level_one + 4 * f.run - h.draw_kl AS level_two, a.cost_one + f.run * h.run_cents AS cost_two FROM first_hour AS a CROSS JOIN flags AS f CROSS JOIN pump_hour AS h WHERE h.hour_no = 2 AND a.level_one BETWEEN 0 AND 5), third_hour AS (SELECT b.run_one, b.run_two, f.run AS run_three, b.cost_two + f.run * h.run_cents AS cost_cents, b.level_two + 4 * f.run - h.draw_kl AS closing_kl FROM second_hour AS b CROSS JOIN flags AS f CROSS JOIN pump_hour AS h WHERE h.hour_no = 3 AND b.level_two BETWEEN 0 AND 5) SELECT run_one, run_two, run_three, cost_cents, closing_kl FROM third_hour WHERE closing_kl BETWEEN 2 AND 5 ORDER BY cost_cents, run_one, run_two, run_three LIMIT 1"
}
